def redirect_to_org(self, request: Request):
    from sentry import features

    # TODO(dcramer): deal with case when the user cannot create orgs
    if self.active_organization:
        url = Organization.get_url(self.active_organization.slug)
    elif not features.has("organizations:create"):
        return self.respond("sentry/no-organization-access.html", status=403)
    else:
        url = "/organizations/new/"
        if request.subdomain:
            base = options.get("system.url-prefix")
            url = f"{base}{url}"
    return HttpResponseRedirect(url)

def is_valid_redirect(url: str, allowed_hosts: Optional[Container] = None) -> bool:
    if not url:
        return False
    if url.startswith(get_login_url()):
        return False
    return is_safe_url(url, allowed_hosts=allowed_hosts)

def get_client_state_redirect_uri(organization_slug, fallback_url):
    if organization_slug:
        state = get_client_state("onboarding", organization_slug, None)
        if (
            state
            and state.get("state") != "finished"
            and state.get("state") != "skipped"
            and state.get("url")
        ):
            return f'/onboarding/{organization_slug}/{state["url"]}'
    return fallback_url
